+static void counting_sort(const uint32_t* src, uint32_t* dst, size_t n, int shift) {
+    static uint32_t hist[256];
+    std::memset(hist, 0, sizeof(hist));
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t d = (src[i] >> shift) & 0xFFu;
+        hist[d]++;
+    }
+    uint32_t offset = 0;
+    for (uint32_t i = 0; i < 256; ++i) {
+        uint32_t h = hist[i];
+        hist[i] = offset;
+        offset += h;
+    }
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t d = (src[i] >> shift) & 0xFFu;
+        dst[ hist[d]++ ] = src[i];
+    }
 }

